SELECT id, bucket_code, region, display_name, created_at FROM storage_buckets
LOWER(bucket_code) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(display_name) LIKE LOWER(CONCAT('%', #{keyword}, '%'))
ORDER BY id ASC LIMIT #{limit} OFFSET #{offset}

SELECT id, bucket_code, region, display_name, created_at
FROM storage_buckets
WHERE bucket_code = #{bucketCode}
